5.1 Shapes
To convert the downloaded GeoTIFF files to Esri ASCII grid format, we developed the worldclim_to_ascii() function, also part of the orbis R package (Vartanian, 2026). Just like worldclim_download(), it is pretty straightforward to use. Here is a overview of its main parameters:
worldclim_to_ascii allow you not only convert the GeoTIFF files to Esri ASCII format, but also crop the data to a specific region of interest. This is done using the shape or box parameters.
The first parameter, shape, expects a spatial object that defines the area to crop. The second parameter, box, allows you to specify a bounding box using numeric coordinates. You can use one or the other, but not both at the same time. If neither is provided, the function will convert the entire dataset without cropping.
To obtain shapes of countries and their administrative boundaries, we recommend using the geodata R package (Hijmans et al., 2024), which provides access to shapes from the GADM database (Hijmans, n.d.). You can install in R with:
And load it with:
library(geodata)
With geodata loaded, use the gadm() function to download country shapes. This function identifies countries using the ISO 3166-1 alpha-3 standard and supports multiple resolutions, from country boundaries (level 0) to administrative subdivisions (levels 1, 2, and 3).
For example, if you want to crop WorldClim data to the boundaries of Brazil, you could use the following code:
country_shape &lt;- gadm("BRA", path = "data", level = 0)
This code will download the shape of Brazil and store it in the country_shape variable, which can then be passed to the shape parameter of the worldclim_to_ascii() function for cropping.
Codelibrary(leaflet)
library(sf)

leaflet() |&gt;
  addProviderTiles(providers$Esri.WorldStreetMap) |&gt;
  fitBounds(
    lng1 = country_shape |&gt;
      st_bbox() |&gt;
      magrittr::extract("xmin") |&gt;
      unname(),
    lat1 = country_shape |&gt;
      st_bbox() |&gt;
      magrittr::extract("ymin") |&gt;
      unname(),
    lng2 = country_shape |&gt;
      st_bbox() |&gt;
      magrittr::extract("xmax") |&gt;
      unname(),
    lat2 = country_shape |&gt;
      st_bbox() |&gt;
      magrittr::extract("ymax") |&gt;
      unname()
  ) |&gt;
  addPolygons(
    data = country_shape,
    fillColor = "transparent",
    color = "blue",
    weight = 2,
    opacity = 1
  )

B.4 Select Random Country

B.4.1 Select Country






The list of countries is based on the ISO 3166-1 alpha-3 standard and draw using the ISOcodes R package (Hornik & Buchta, 2025).




country &lt;-
  country_names("alpha 3") |&gt;
  str_subset("ATA", negate = TRUE) |&gt;
  sample(1)


country
#&gt; Mexico 
#&gt;  "MEX"


B.4.2 Download Country Shape






The rspatial geodata R package (Hijmans et al., 2024) is used to download country shapes from the GADM database (Hijmans, n.d.).




country_shape &lt;-
  country |&gt;
  gadm(
    level = 0,
    path = path(data_dir),
    resolution = 1
  )
#&gt; Cached as: /home/runner/work/logoclim/logoclim/.data-temp/gadm/gadm41_MEX_0_pk.rds


B.4.3 Calculate Shape Area

shape_area &lt;-
  country_shape |&gt;
  expanse(unit = "km") |&gt;
  magrittr::extract(1)







This while loop filters out micronations. The country’s area is divided by 21 km², the approximate area of a single cell at 2.5-minute resolution at the Equator. This resolution was chosen because it’s the highest available across all three WorldClim datasets (the Historical Monthly Weather Data series tops out at 2.5 minutes). The division ensures the selected country has enough area to yield at least 1,000 cells for analysis.




while (!(shape_area / 21 &gt;= 1000)) {
  country &lt;- country_names("alpha 3") |&gt; sample(1)

  country_shape &lt;-
    country |&gt;
    gadm(
      level = 0,
      path = path(data_dir),
      resolution = 1
    )

  shape_area &lt;-
    country_shape |&gt;
    expanse(unit = "km") |&gt;
    magrittr::extract(1)
}


shape_area
#&gt; [1] 1951230.548


country
#&gt; Mexico 
#&gt;  "MEX"


B.4.4 Visualize Country Shape






The rotate() function from the terra package (Hijmans, 2026) is used to adjust shapes that cross the International Date Line (IDL) (e.g., Russian territory).
This adjustment applies only for visualizing countries on leaflet and does not affect the near-equality tests. The Esri ASCII transformation function (worldclim_to_ascii()), used to prepare data for NetLogo, applies the necessary rotation to ensure proper alignment of the raster data with the model’s patch grid.




idl_countries &lt;- list(
  "FJI" = list(left = FALSE),
  "KIR" = list(left = TRUE),
  "NZL" = list(left = FALSE),
  "RUS" = list(left = FALSE),
  "USA" = list(left = TRUE)
)


if (country %in% names(idl_countries)) {
  country_shape_leaflet &lt;-
    country_shape |&gt;
    rotate(left = idl_countries[[country]]$left)
} else {
  country_shape_leaflet &lt;- country_shape
}


leaflet() |&gt;
  addProviderTiles(providers$Esri.WorldStreetMap) |&gt;
  fitBounds(
    lng1 = country_shape_leaflet |&gt;
      st_bbox() |&gt;
      magrittr::extract("xmin") |&gt;
      unname(),
    lat1 = country_shape_leaflet |&gt;
      st_bbox() |&gt;
      magrittr::extract("ymin") |&gt;
      unname(),
    lng2 = country_shape_leaflet |&gt;
      st_bbox() |&gt;
      magrittr::extract("xmax") |&gt;
      unname(),
    lat2 = country_shape_leaflet |&gt;
      st_bbox() |&gt;
      magrittr::extract("ymax") |&gt;
      unname()
  ) |&gt;
  addPolygons(
    data = country_shape_leaflet,
    fillColor = "transparent",
    color = "blue",
    weight = 2,
    opacity = 1
  )

C.4 as-list


setup_file &lt;- create_experiment(
  name = "as-list",
  setup = "setup false",
  go = NULL,
  metrics = c(
    'as-list "a"',
    'as-list 1',
    'as-list true',
    'as-list [1 2 3]'
  )
)


results &lt;-
  model_path |&gt;
  run_experiment(
    setup_file = setup_file
  )
#&gt; ℹ Running model
#&gt; ✔ Running model [5.8s]
#&gt; 
#&gt; ℹ Gathering metadata
#&gt; ✔ Gathering metadata [11ms]
#&gt; 
#&gt; ℹ Processing table output
#&gt; ✔ Processing table output [16ms]
#&gt; 
#&gt; ℹ The experiment run produced the following messages:
#&gt; 
#&gt; Picked up JAVA_TOOL_OPTIONS: -Dcom.sun.media.jai.disableMediaLib=true


results |&gt;
  pluck("table") |&gt;
  glimpse()
#&gt; Rows: 1
#&gt; Columns: 6
#&gt; $ run_number    &lt;dbl&gt; 1
#&gt; $ step          &lt;dbl&gt; 1
#&gt; $ as_list_a     &lt;chr&gt; "[a]"
#&gt; $ as_list_1     &lt;chr&gt; "[1]"
#&gt; $ as_list_true  &lt;chr&gt; "[true]"
#&gt; $ as_list_1_2_3 &lt;chr&gt; "[1 2 3]"


test_that("as-list", {
  results |&gt;
    pluck("table") |&gt;
    pull(as_list_a) |&gt;
    expect_equal("[a]")

  results |&gt;
    pluck("table") |&gt;
    pull(as_list_1) |&gt;
    expect_equal("[1]")

  results |&gt;
    pluck("table") |&gt;
    pull(as_list_true) |&gt;
    expect_equal("[true]")

  results |&gt;
    pluck("table") |&gt;
    pull(as_list_1_2_3) |&gt;
    expect_equal("[1 2 3]")
})
#&gt; Test passed with 4 successes 🎉.

C.5 quartile


setup_file &lt;- create_experiment(
  name = "quartile",
  setup = "setup false",
  go = NULL,
  metrics = c(
    'quartile [0 1 2 3 4] 0',
    'quartile [0 1 2 3 4] 1',
    'quartile [0 1 2 3 4] 2',
    'quartile [0 1 2 3 4] 3',
    'quartile [0 1 2 3 4] 4',
    'quartile [0 1 2 3 4] "iqr"',
    'quartile [0 1 2 3 4] "length"',
    'quartile [0 1 2 3 4 5] 0',
    'quartile [0 1 2 3 4 5] 1',
    'quartile [0 1 2 3 4 5] 2',
    'quartile [0 1 2 3 4 5] 3',
    'quartile [0 1 2 3 4 5] 4',
    'quartile [0 1 2 3 4 5] "iqr"',
    'quartile [0 1 2 3 4 5] "length"'
  )
)


results &lt;-
  model_path |&gt;
  run_experiment(
    setup_file = setup_file
  )
